const response =
  $json?.body && typeof $json.body === 'object'
    ? $json.body
    : ($json || {});

const statusCode = Number(response?.status?.code);
const token = String(
  response?.result?.token ||
  response?.token ||
  ''
).trim();

if (statusCode !== 200 || !token) {
  throw new Error(
    'Не удалось обновить токен Seldon по расписанию. ' +
    `Код: ${response?.status?.code ?? 'не указан'}. ` +
    `Описание: ${response?.status?.descr || response?.message || 'нет описания'}`
  );
}

const now = Date.now();
const staticData = $getWorkflowStaticData('global');

staticData.seldonToken = token;
staticData.seldonTokenCreatedAt = new Date(now).toISOString();
staticData.seldonTokenExpiresAt = new Date(
  now + 23.5 * 60 * 60 * 1000
).toISOString();

return [{
  json: {
    status: 'ok',
    action: 'seldon_token_refreshed',
    tokenCreatedAt: staticData.seldonTokenCreatedAt,
    tokenExpiresAt: staticData.seldonTokenExpiresAt,
    tokenPreview: `${token.slice(0, 4)}…${token.slice(-4)}`
  }
}];

const source = $json || {};
const staticData = $getWorkflowStaticData('global');

const inputToken = String(
  source.seldonToken ||
  source.token ||
  ''
).trim();

const cachedToken = String(staticData.seldonToken || '').trim();
const expiresAt = Date.parse(String(staticData.seldonTokenExpiresAt || ''));

const cachedValid =
  Boolean(cachedToken) &&
  Number.isFinite(expiresAt) &&
  expiresAt > Date.now() + 5 * 60 * 1000;

// Переданный во входном JSON token считаем пригодным для попытки запроса.
// Если он неверный/истёкший, HTTP-нода вернёт ошибку; тогда рекомендуется отдельная retry-ветка через Login.
const token = inputToken || (cachedValid ? cachedToken : '');
const valid = Boolean(token);
const tokenSource = inputToken ? 'input_json' : (cachedValid ? 'workflow_static_data' : 'none');

const logs = [...(source.logs || [])];
logs.push({
  time: new Date().toISOString(),
  step: 'Проверка токена Seldon',
  status: valid ? 'ok' : 'warning',
  details: valid
    ? `Используется токен из источника: ${tokenSource}.`
    : 'Токен не передан и сохранённый токен отсутствует или истёк. Будет выполнена авторизация.'
});

return [{
  json: {
    ...source,
    seldonToken: token,
    seldonTokenValid: valid,
    seldonTokenSource: tokenSource,
    seldonTokenCreatedAt: inputToken ? null : (staticData.seldonTokenCreatedAt || null),
    seldonTokenExpiresAt: inputToken ? null : (staticData.seldonTokenExpiresAt || null),
    logs
  }
}];

const base = $('Load Seldon Token1').first().json || {};

const response =
  $json?.body && typeof $json.body === 'object'
    ? $json.body
    : ($json || {});

const statusCode = Number(response?.status?.code);
const token = String(
  response?.result?.token ||
  response?.token ||
  ''
).trim();

if (statusCode !== 200 || !token) {
  throw new Error(
    'Не удалось авторизоваться в Seldon API. ' +
    `Код: ${response?.status?.code ?? 'не указан'}. ` +
    `Описание: ${response?.status?.descr || response?.message || 'нет описания'}`
  );
}

const now = Date.now();
const staticData = $getWorkflowStaticData('global');

staticData.seldonToken = token;
staticData.seldonTokenCreatedAt = new Date(now).toISOString();
staticData.seldonTokenExpiresAt = new Date(
  now + 23.5 * 60 * 60 * 1000
).toISOString();

const logs = [...(base.logs || [])];

logs.push({
  time: new Date().toISOString(),
  step: 'Авторизация Seldon API',
  status: 'ok',
  details: 'Получен и сохранён новый токен Seldon.'
});

return [{
  json: {
    ...base,
    seldonToken: token,
    seldonTokenValid: true,
    seldonTokenCreatedAt: staticData.seldonTokenCreatedAt,
    seldonTokenExpiresAt: staticData.seldonTokenExpiresAt,
    logs
  }
}];

function unwrapResponse(value) {
  if (value?.body && typeof value.body === 'object') return value.body;
  return value || {};
}

function statusCode(response) {
  const raw = response?.status?.code;
  const number = Number(raw);
  return Number.isFinite(number) ? number : null;
}

function statusDescription(response) {
  return String(
    response?.status?.descr ||
    response?.message ||
    response?.error ||
    ''
  ).trim();
}

function toArray(value) {
  if (Array.isArray(value)) return value;
  if (value && typeof value === 'object') return [value];
  return [];
}

function firstValue(object, keys) {
  for (const key of keys) {
    const value = object?.[key];
    if (value !== undefined && value !== null && value !== '') return value;
  }
  return null;
}

function normalizeExtension(value) {
  const text = String(value || '').trim().toLowerCase();
  if (!text) return '';
  return text.startsWith('.') ? text : `.${text}`;
}

function buildFileName(document, index) {
  const extension = normalizeExtension(
    firstValue(document, ['fileType', 'extension', 'ext'])
  );

  let name = String(
    firstValue(document, ['name', 'fileName', 'filename', 'title']) ||
    `seldon_document_${index}`
  ).trim();

  if (extension && !name.toLowerCase().endsWith(extension)) {
    name += extension;
  }

  return name;
}

const base =
  $('Use Input Seldon Purchase1').first().json || {};

const purchaseResponse =
  unwrapResponse(base.seldonPurchaseResponse);

const documentsResponse =
  unwrapResponse($json);

const purchaseApiCode = statusCode(purchaseResponse);

if (purchaseApiCode !== 200) {
  throw new Error(
    'Seldon API не вернул данные закупки. ' +
    `Код: ${purchaseResponse?.status?.code ?? 'не указан'}. ` +
    `Описание: ${statusDescription(purchaseResponse) || 'нет описания'}.`
  );
}

const purchaseResult = purchaseResponse?.result || {};

let purchases = toArray(purchaseResult?.purchases);

if (!purchases.length) {
  purchases = toArray(purchaseResult?.purchase);
}

if (!purchases.length) {
  const looksLikePurchase =
    firstValue(purchaseResult, ['seldonId', 'seldonID', 'etpId', 'reportId']) !== null;

  if (looksLikePurchase) purchases = [purchaseResult];
}

if (!purchases.length) {
  throw new Error(
    'В успешном ответе /Purchases/Get отсутствует объект закупки.'
  );
}

const purchase = purchases[0];

const warnings = [...(base.warnings || [])];
const logs = [...(base.logs || [])];

if (purchases.length > 1) {
  warnings.push(
    `Метод /Purchases/Get вернул ${purchases.length} объектов. Для обработки выбран первый объект.`
  );
}

const documentsApiCode = statusCode(documentsResponse);
const documentsResult = documentsResponse?.result || {};

let documentGroups = [];

if (documentsApiCode === 200) {
  documentGroups = toArray(
    documentsResult?.purchasesdocuments ||
    documentsResult?.purchaseDocuments ||
    documentsResult?.documentsByPurchase
  );

  if (!documentGroups.length && Array.isArray(documentsResult?.documents)) {
    documentGroups = [{
      seldonId: firstValue(purchase, ['seldonId', 'seldonID', 'SeldonId']),
      documents: documentsResult.documents
    }];
  }
} else {
  warnings.push(
    'Документы Seldon не получены. ' +
    `Код: ${documentsResponse?.status?.code ?? 'не указан'}. ` +
    `Описание: ${statusDescription(documentsResponse) || 'нет описания'}. ` +
    'Обработка продолжена по структурированным данным закупки.'
  );
}

const rawDocuments = documentGroups.flatMap(group => {
  const documents = Array.isArray(group?.documents)
    ? group.documents
    : [];

  return documents.map(document => ({
    ...document,
    parentSeldonId: firstValue(
      group,
      ['seldonId', 'seldonID', 'SeldonId', 'id']
    )
  }));
});

const documentFiles = rawDocuments
  .filter(document => {
    const version = firstValue(document, ['Version', 'version']);

    if (
      version === 0 ||
      version === false ||
      String(version).trim() === '0'
    ) {
      return false;
    }

    return Boolean(
      firstValue(
        document,
        ['urlSeldon', 'urlSource', 'url', 'downloadUrl']
      )
    );
  })
  .map((document, index) => {
    const urlSeldon = firstValue(document, ['urlSeldon']);
    const urlSource = firstValue(document, ['urlSource']);
    const fallbackUrl = firstValue(document, ['url', 'downloadUrl']);
    const selectedUrl = urlSeldon || urlSource || fallbackUrl;

    return {
      index: index + 1,
      id: firstValue(document, ['id', 'Id', 'documentId']),

      url: String(selectedUrl),
      urlSeldon: urlSeldon ? String(urlSeldon) : null,
      urlSource: urlSource ? String(urlSource) : null,
      source: urlSeldon ? 'seldon' : (urlSource ? 'source' : 'other'),

      fileName: buildFileName(document, index + 1),
      fileType: firstValue(document, ['fileType', 'extension', 'ext']),
      fileSize: firstValue(document, ['fileSize', 'size']),
      version: firstValue(document, ['Version', 'version']),
      publishDate: firstValue(document, ['publishDate']),
      parentSeldonId: document.parentSeldonId
    };
  });

const seldonId =
  firstValue(purchase, ['seldonId', 'seldonID', 'SeldonId', 'id']) ||
  base.seldonId ||
  null;

const reportId =
  Number(firstValue(purchase, ['reportId', 'ReportId']) || base.reportId) ||
  base.reportId;

const etpId =
  firstValue(
    purchase,
    ['etpId', 'EtpId', 'notificationNumber', 'purchaseNumber', 'number']
  ) ||
  base.etpId ||
  null;

const purchaseNumber = etpId || base.purchaseNumber || null;

const tenderUrl =
  firstValue(
    purchase,
    [
      'urlSource',
      'purchaseUrl',
      'tenderUrl',
      'url',
      'link',
      'sourceUrl',
      'href'
    ]
  ) ||
  base.tenderUrl ||
  null;

const subject = firstValue(
  purchase,
  ['subject', 'purchaseSubject', 'name', 'purchaseName', 'description']
);

const initialPrice = firstValue(
  purchase,
  ['price', 'purchasePrice', 'initialPrice', 'maxPrice', 'nmck']
);

const publishDate = firstValue(
  purchase,
  ['publishDate', 'firstPublishDate', 'datePublish']
);

const startDate = firstValue(
  purchase,
  ['dateStart', 'startDate', 'submissionStartDate']
);

const endDate = firstValue(
  purchase,
  ['dateEnd', 'endDate', 'submissionDeadline', 'submissionEndDate']
);

function parseRemainingDays(value) {
  let raw = value;

  if (
    raw &&
    typeof raw === 'object' &&
    !Array.isArray(raw) &&
    'value' in raw
  ) {
    raw = raw.value;
  }

  const match = String(raw ?? '')
    .replace(',', '.')
    .match(/-?\d+(?:\.\d+)?/);

  if (!match) {
    return null;
  }

  const number = Number(match[0]);

  return Number.isFinite(number)
    ? number
    : null;
}

const remainingDaysRaw =
  base.remainingDays ??
  base.remainingDaysRaw ??
  base.reportFields?.['Осталось дней'] ??
  purchase.remainingBusinessDays ??
  null;

const remainingDays =
  parseRemainingDays(remainingDaysRaw);

const activeDocumentMetadata = documentFiles.map(document => ({
  id: document.id,
  fileName: document.fileName,
  fileType: document.fileType,
  fileSize: document.fileSize,
  version: document.version,
  publishDate: document.publishDate,
  source: document.source
}));

const pageText = [
  '--- ДАННЫЕ ЗАКУПКИ ИЗ SELDON API ---',
  `Seldon ID: ${seldonId ?? ''}`,
  `Report ID: ${reportId ?? ''}`,
  `Номер закупки на площадке: ${purchaseNumber ?? ''}`,
  `Предмет закупки: ${subject ?? ''}`,
  `Начальная цена / НМЦ: ${initialPrice ?? ''}`,
  `Дата публикации: ${publishDate ?? ''}`,
  `Дата начала подачи: ${startDate ?? ''}`,
  `Дата окончания подачи: ${endDate ?? ''}`,
  `Ссылка на источник: ${tenderUrl ?? ''}`,
  '',
  '--- ПОЛНЫЕ СТРУКТУРИРОВАННЫЕ ДАННЫЕ SELDON ---',
  JSON.stringify(purchase, null, 2),
  '',
  '--- АКТУАЛЬНЫЕ ДОКУМЕНТЫ SELDON ---',
  JSON.stringify(activeDocumentMetadata, null, 2)
].join('\n');

logs.push({
  time: new Date().toISOString(),
  step: 'Получение закупки и документов из Seldon',
  status: 'ok',
  details:
    `seldonId=${seldonId ?? 'не указан'}; ` +
    `reportId=${reportId ?? 'не указан'}; ` +
    `etpId=${etpId ?? 'не указан'}; ` +
    `документов=${documentFiles.length}; ` +
    `длина структурированного текста=${pageText.length}`
});

return [{
  json: {
    ...base,

    inputSource: 'seldon_api',

    seldonId,
    reportId,
    etpId,
    purchaseNumber,
    tenderUrl,

    pageText,
    htmlLength: pageText.length,

    seldonPurchase: purchase,

    // Явно сохраняем служебные поля на верхнем уровне.
    // Они не должны извлекаться моделью из pageText.
    toCode:
      firstValue(purchase, ['toCode', 'Код ТО']) ??
      base.toCode ??
      base.reportFields?.['Код ТО'] ??
      null,
    lawCode:
      firstValue(purchase, ['lawCode', 'Код ФЗ']) ??
      base.lawCode ??
      base.reportFields?.['Код ФЗ'] ??
      null,
    reportFields:
      base.reportFields &&
      typeof base.reportFields === 'object' &&
      !Array.isArray(base.reportFields)
        ? { ...base.reportFields }
        : {},
    batchId: base.batchId ?? null,
    batchDate: base.batchDate ?? null,
    rowNumber: base.rowNumber ?? null,

    // Не включаем это поле в pageText и не поручаем его извлечение модели.
    remainingDays,
    remainingDaysRaw:
      remainingDaysRaw ?? null,

    sectionName: base.sectionName ?? null,
    filterName: base.filterName ?? null,

    seldonPurchaseResponseStatus: purchaseResponse?.status || null,
    seldonDocumentsResponseStatus: documentsResponse?.status || null,

    documentFiles,
    documentLinks: documentFiles.map(document => document.url),
    documentCount: documentFiles.length,

    documentsPageUrl: tenderUrl || base.seldonBaseUrl,

    logs,
    warnings: [...new Set(warnings.map(String))]
  }
}];

function fixMojibake(value) {
  const s = String(value || '');
  if (!s) return '';
  if (/[ÐÑ]/.test(s)) {
    try { return Buffer.from(s, 'latin1').toString('utf8'); } catch {}
  }
  return s;
}

function extensionFromName(name) {
  const clean = String(name || '').split('?')[0].split('#')[0].trim();
  const match = clean.match(/\.([a-z0-9]{2,6})$/i);
  return match ? match[1].toLowerCase() : '';
}

function extensionFromMime(mime) {
  const m = String(mime || '').toLowerCase();

  if (m.includes('pdf')) return 'pdf';

  if (m.includes('wordprocessingml')) return 'docx';
  if (m.includes('msword')) return 'doc';

  if (m.includes('spreadsheetml')) return 'xlsx';
  if (m.includes('vnd.ms-excel')) return 'xls';
  if (m.includes('excel')) return 'xlsx';
  if (m.includes('csv')) return 'csv';

  if (
    m === 'application/zip' ||
    m.includes('x-zip-compressed')
  ) return 'zip';

  if (
    m.includes('x-rar-compressed') ||
    m.includes('vnd.rar')
  ) return 'rar';

  if (
    m.includes('x-7z-compressed') ||
    m.includes('7z')
  ) return '7z';

  return '';
}

function extensionFromMagic(binary) {
  const raw = binary?.data;

  // При filesystem/S3 binary storage в поле data может быть не base64,
  // поэтому magic-byte проверка является только дополнительной защитой.
  if (typeof raw !== 'string' || !raw || raw.length < 8) return '';

  try {
    const buffer = Buffer.from(raw, 'base64');
    if (buffer.length < 4) return '';

    const first8 = [...buffer.subarray(0, 8)];

    // ZIP: PK\x03\x04, PK\x05\x06, PK\x07\x08
    if (
      first8[0] === 0x50 &&
      first8[1] === 0x4b &&
      (
        (first8[2] === 0x03 && first8[3] === 0x04) ||
        (first8[2] === 0x05 && first8[3] === 0x06) ||
        (first8[2] === 0x07 && first8[3] === 0x08)
      )
    ) return 'zip';

    // RAR 4/5
    if (
      first8[0] === 0x52 &&
      first8[1] === 0x61 &&
      first8[2] === 0x72 &&
      first8[3] === 0x21 &&
      first8[4] === 0x1a &&
      first8[5] === 0x07
    ) return 'rar';

    // 7z
    if (
      first8[0] === 0x37 &&
      first8[1] === 0x7a &&
      first8[2] === 0xbc &&
      first8[3] === 0xaf &&
      first8[4] === 0x27 &&
      first8[5] === 0x1c
    ) return '7z';

    // PDF
    if (
      first8[0] === 0x25 &&
      first8[1] === 0x50 &&
      first8[2] === 0x44 &&
      first8[3] === 0x46
    ) return 'pdf';
  } catch {}

  return '';
}

function parserRoute(ext) {
  if (ext === 'docx' || ext === 'doc') return 'word';
  if (ext === 'pdf') return 'pdf';
  if (ext === 'xlsx' || ext === 'xls' || ext === 'csv') return 'spreadsheet';
  if (ext === 'zip') return 'zip';
  if (ext === 'rar') return 'rar';
  if (ext === '7z') return 'archive7z';
  return 'unknown';
}

function isArchiveExtension(ext) {
  return ['zip', 'rar', '7z'].includes(String(ext || '').toLowerCase());
}

return $input.all().map((item, i) => {
  const j = item.json || {};
  const b = item.binary?.data || {};

  const binaryFileName = fixMojibake(
    b.fileName ||
    b.filename ||
    ''
  );

  const declaredFileName = fixMojibake(
    j.documentFileName ||
    j.fileName ||
    j.filename ||
    ''
  );

  const binaryExt = extensionFromName(binaryFileName);
  const declaredExt = extensionFromName(declaredFileName);
  const urlExt = extensionFromName(j.documentUrl || '');
  const mimeExt = extensionFromMime(b.mimeType || j.mimeType || '');
  const magicExt = extensionFromMagic(b);

  /*
   * ЖЁСТКИЙ ПРИОРИТЕТ:
   * 1) фактическое имя скачанного binary;
   * 2) имя из Seldon;
   * 3) URL;
   * 4) MIME;
   * 5) magic bytes.
   *
   * Если фактическое имя заканчивается на .zip/.rar/.7z,
   * архив никогда не должен попасть в Universal File Extractor.
   */
  let ext = binaryExt || declaredExt || urlExt || mimeExt || magicExt || 'unknown';
  let selectedTypeSource =
    binaryExt ? 'binary_file_name' :
    declaredExt ? 'seldon_file_name' :
    urlExt ? 'document_url' :
    mimeExt ? 'mime_type' :
    magicExt ? 'magic_bytes' :
    'unknown';

  if (isArchiveExtension(binaryExt)) {
    ext = binaryExt;
    selectedTypeSource = 'binary_archive_file_name_forced';
  } else if (
    !binaryExt &&
    isArchiveExtension(magicExt) &&
    !['docx', 'xlsx'].includes(declaredExt)
  ) {
    ext = magicExt;
    selectedTypeSource = 'archive_magic_bytes_forced';
  }

  const route = parserRoute(ext);
  const fileName =
    binaryFileName ||
    declaredFileName ||
    `document_${i + 1}.${ext === 'unknown' ? 'bin' : ext}`;

  const mimeType = b.mimeType || j.mimeType || '';
  const fileSize = b.fileSize || j.fileSize || '';

  const mismatch =
    Boolean(binaryExt) &&
    Boolean(declaredExt) &&
    binaryExt !== declaredExt;

  const warnings = Array.isArray(j.warnings)
    ? [...j.warnings]
    : [];

  const mismatchWarning = mismatch
    ? `Фактический файл (${binaryFileName}, .${binaryExt}) не совпадает с метаданными Seldon (${declaredFileName}, .${declaredExt}). Маршрут выбран по фактическому binary-файлу.`
    : '';

  const archiveGuardWarning =
    isArchiveExtension(binaryExt) && route !== 'word'
      ? `Защита архивов: файл .${binaryExt} принудительно направлен в ветку ${route}.`
      : '';

  const unknownWarning =
    route === 'unknown'
      ? 'Тип файла не определён или не поддерживается текущим workflow.'
      : '';

  for (const warning of [mismatchWarning, archiveGuardWarning, unknownWarning]) {
    if (warning) warnings.push(warning);
  }

  return {
    json: {
      ...j,

      declaredDocumentFileName: declaredFileName || null,
      binaryFileName: binaryFileName || null,

      binaryExtension: binaryExt || null,
      declaredExtension: declaredExt || null,
      urlExtension: urlExt || null,
      mimeExtension: mimeExt || null,
      magicExtension: magicExt || null,
      selectedTypeSource,
      fileTypeMismatch: mismatch,

      documentIndex: j.documentIndex || i + 1,
      documentFileName: fileName,
      fileExtension: ext,
      mimeType,
      fileSize,

      parserRoute: route,

      // Независимое поле для аварийной проверки перед Word extractor.
      archiveSafetyRoute:
        isArchiveExtension(binaryExt)
          ? parserRoute(binaryExt)
          : route,

      parserWarning: [
        j.parserWarning,
        mismatchWarning,
        archiveGuardWarning,
        unknownWarning
      ].filter(Boolean).join(' '),

      warnings: [...new Set(warnings.map(String))]
    },
    binary: item.binary
  };
});

// Validate Fields2 получает контекст напрямую от предыдущей ноды.
// Нельзя использовать $('...').first(): в циклах/повторных запусках n8n
// это может вернуть первый item другой итерации, где toCode/reportId уже другие или пустые.
const source = $json || {};
const logs = [...(source.logs || [])];
const warnings = [...(source.warnings || [])];
const allText = String(source.combinedText || source.pageText || '');

function getAgentContent(j) {
  if (!j) return '';
  if (typeof j.output === 'string') return j.output;
  if (typeof j.text === 'string') return j.text;
  if (typeof j.response === 'string') return j.response;
  if (typeof j.content === 'string') return j.content;
  if (typeof j.message === 'string') return j.message;
  if (j.data && typeof j.data === 'string') return j.data;
  const c = j.choices?.[0]?.message?.content || j.body?.choices?.[0]?.message?.content;
  if (typeof c === 'string') return c;
  return '';
}
function extractJson(text) {
  const s = String(text || '').trim();
  if (!s) return null;
  try { return JSON.parse(s); } catch {}
  const fenced = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced?.[1]) { try { return JSON.parse(fenced[1].trim()); } catch {} }
  const first = s.indexOf('{'); const last = s.lastIndexOf('}');
  if (first >= 0 && last > first) { try { return JSON.parse(s.slice(first, last + 1)); } catch {} }
  return null;
}
function valOf(x) { return x && typeof x === 'object' && 'value' in x ? x.value : x; }
function normalizeConfidence(c) { const s = String(c || '').toLowerCase(); return ['low','medium','high'].includes(s) ? s : 'low'; }
function metaOf(x) {
  if (x && typeof x === 'object') return { source: String(x.source || '').trim(), confidence: normalizeConfidence(x.confidence || 'low'), evidence: String(x.evidence || '').trim() };
