}
function normalizeDate(v) {
  if (!v) return v;
  const s = String(v).trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const ru = s.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/);
  if (ru) return `${ru[3]}-${ru[2].padStart(2, '0')}-${ru[1].padStart(2, '0')}`;
  const ruText = s.match(/(\d{1,2})\s+(января|февраля|марта|апреля|мая|июня|июля|августа|сентября|октября|ноября|декабря)\s+(\d{4})/i);
  if (ruText) {
    const months = {января:'01',февраля:'02',марта:'03',апреля:'04',мая:'05',июня:'06',июля:'07',августа:'08',сентября:'09',октября:'10',ноября:'11',декабря:'12'};
    return `${ruText[3]}-${months[ruText[2].toLowerCase()]}-${ruText[1].padStart(2, '0')}`;
  }
  return s;
}
function normalizeTime(v) {
  if (!v) return v;
  const m = String(v).match(/(\d{1,2})[:.](\d{2})/);
  return m ? `${m[1].padStart(2,'0')}:${m[2]}` : String(v).trim();
}
function addDays(dateStr, days) {
  if (!dateStr) return null;
  const date = new Date(`${dateStr}T00:00:00.000Z`);
  if (Number.isNaN(date.getTime())) return null;
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
}
function findFirst(text, patterns) { for (const p of patterns) { const m = String(text || '').match(p); if (m?.[1]) return m[1].trim(); } return null; }
function hasAny(text, words) { const t = String(text || '').toLowerCase(); return words.some(w => t.includes(String(w).toLowerCase())); }
