function collectStringCandidates(value, path = '') {
  const out = [];

  if (value === null || value === undefined) return out;

  if (typeof value === 'string') {
    const s = value.trim();
    if (s) out.push({ path, text: s });
    return out;
  }

  if (Array.isArray(value)) {
    value.forEach((v, i) => out.push(...collectStringCandidates(v, `${path}[${i}]`)));
    return out;
  }

  if (typeof value === 'object') {
    for (const [key, v] of Object.entries(value)) {
      const p = path ? `${path}.${key}` : key;
      out.push(...collectStringCandidates(v, p));
    }
  }

  return out;
}

function isMetadataPath(path) {
  const p = String(path || '').toLowerCase();

  return [
    'url',
    'href',
    'filename',
    'filename',
    'fileextension',
    'mimetype',
    'filesize',
    'documenturl',
    'documentfilename',
    'documentindex',
    'tenderurl',
    'purchasenumber',
    'parserroute',
    'parserstatus',
    'parserwarning',
    'parsererror',
    'logs',
    'warnings'
  ].some(x => p.endsWith(x) || p.includes(`.${x}`));
}

function isMostlyUrl(text) {
  const s = String(text || '').trim();
  if (/^https?:\/\/\S+$/i.test(s)) return true;

  const words = s.split(/\s+/).filter(Boolean);
  const urlWords = words.filter(w => /^https?:\/\//i.test(w) || /zakupki\.gov\.ru/i.test(w));
  return words.length > 0 && urlWords.length / words.length > 0.7;
}

function isUsefulText(text) {
  const s = String(text || '').trim();

  if (s.length < 500) return false;
  if (isMostlyUrl(s)) return false;
  if (/^https?:\/\/\S+$/i.test(s)) return false;
  if (s.includes('zakupki.gov.ru/epz/order/notice') && s.length < 1000) return false;

  // Если нет кириллицы/латиницы и нет цифр — скорее всего мусор/пустой результат.
  if (!/[а-яёa-z0-9]/i.test(s)) return false;

  return true;
}

function pickBestText(json) {
  const candidates = collectStringCandidates(json)
    .filter(c => !isMetadataPath(c.path))
    .map(c => ({ ...c, text: String(c.text || '').trim() }))
    .filter(c => c.text);

  const useful = candidates
    .filter(c => isUsefulText(c.text))
    .sort((a, b) => b.text.length - a.text.length);

  if (useful.length) {
    return {
      text: useful[0].text,
      sourcePath: useful[0].path,
      qualityOk: true,
      rawCandidateCount: candidates.length
    };
  }

  const longest = candidates.sort((a, b) => b.text.length - a.text.length)[0];

  return {
    text: longest ? longest.text : '',
    sourcePath: longest ? longest.path : '',
    qualityOk: false,
    rawCandidateCount: candidates.length
  };
}

return $input.all().map((item) => {
  const j = item.json || {};
  const picked = pickBestText(j);
  const text = picked.qualityOk ? picked.text : '';
  const rawPreview = picked.text ? picked.text.slice(0, 500) : '';

  return {
    json: {
      ...j,
      parsedText: text,
      rawExtractedTextPreview: rawPreview,
      extractedTextSourcePath: picked.sourcePath,
      extractedTextCandidateCount: picked.rawCandidateCount,
      extractedTextQualityOk: picked.qualityOk,
      extractedTextLength: picked.text ? picked.text.length : 0,
      parserStatus: picked.qualityOk ? 'ok' : (j.error ? 'word_extractor_error' : 'not_parsed_quality_failed'),
      parserError: j.error || j.message || '',
      parserWarning: picked.qualityOk
        ? ''
        : `Universal File Extractor / Word Extractor не вернул полезный текст: длина кандидата ${picked.text ? picked.text.length : 0}, sourcePath=${picked.sourcePath || 'none'}. Возможно .doc нужен через LibreOffice/parser-service.`
    },
