}

function resolveReportId(typeValue, explicitReportId) {
  const explicit = Number(explicitReportId);
  if ([1, 2, 3, 4, 5].includes(explicit)) {
    return { reportId: explicit, source: 'reportId' };
  }

  const type = normalizePurchaseType(typeValue);
  const aliases = new Map([
    ['1', 1],
    ['223-фз', 1],
    ['223 фз', 1],
    ['223', 1],

    ['2', 2],
    ['44/94-фз', 2],
    ['44/94 фз', 2],
    ['44-фз', 2],
    ['44 фз', 2],
    ['94-фз', 2],
    ['94 фз', 2],
    ['44', 2],
    ['94', 2],

    ['3', 3],
    ['коммерческие закупки', 3],
    ['коммерческая закупка', 3],
    ['коммерческие', 3],
    ['коммерческая', 3],
    ['commercial', 3],

    ['4', 4],
    ['контракты', 4],
    ['контракт', 4],
    ['contracts', 4],

    ['5', 5],
    ['международные закупки', 5],
    ['международная закупка', 5],
    ['международные', 5],
    ['международная', 5],
    ['international', 5]
  ]);

  const reportId = aliases.get(type);
  if (!reportId) {
    throw new Error(
      'Не удалось определить reportId по типу закупки. ' +
      'Передайте purchaseType/tenderType одним из значений: ' +
      '223-ФЗ, 44/94-ФЗ, Коммерческие закупки, Контракты, Международные закупки.'
    );
  }

  return { reportId, source: 'purchaseType' };
}


