function buildReportFields(source, reportId, toCode, lawCode) {
  const supplied =
    source?.reportFields &&
    typeof source.reportFields === 'object' &&
    !Array.isArray(source.reportFields)
      ? source.reportFields
      : {};

  const result = {};

  for (const header of REPORT_HEADERS[reportId] || []) {
    result[header] = supplied[header] ?? source?.[header] ?? '';
  }

  if ('SeldonID' in result && !result.SeldonID) {
    result.SeldonID = firstDefined(
      source?.seldonId,
      source?.SeldonId,
      source?.SeldonID,
      source?.ID
    ) ?? '';
  }

  if ('Код ТО' in result && !result['Код ТО']) {
    result['Код ТО'] = toCode ?? '';
  }

  if ('Код ФЗ' in result && !result['Код ФЗ']) {
    result['Код ФЗ'] = lawCode ?? '';
  }

  return result;
}

