function parseRemainingDays(value) {
  let raw = value;

  if (
    raw &&
    typeof raw === 'object' &&
    !Array.isArray(raw) &&
    'value' in raw
  ) {
    raw = raw.value;
  }

  const text = String(raw ?? '')
    .replace(',', '.')
    .trim();

  const match = text.match(/-?\d+(?:\.\d+)?/);

  if (!match) {
    return null;
  }

  const number = Number(match[0]);

  return Number.isFinite(number)
    ? number
    : null;
}

