function looksGarbled(name) {
  const s = String(name || '');
  return /[\u0080-\u009F]/.test(s) || /[]/.test(s);
}

function fixMojibake(value, fallback = '') {
  const s = String(value || '');
  if (!s) return fallback || '';
  if (/[ÐÑ]/.test(s)) {
    try { return Buffer.from(s, 'latin1').toString('utf8'); } catch {}
  }
  if (looksGarbled(s)) return fallback || s;
  return s;
}

function isMostlyUrl(text) {
  const s = String(text || '').trim();
  if (/^https?:\/\/\S+$/i.test(s)) return true;

  const words = s.split(/\s+/).filter(Boolean);
  const urlWords = words.filter(w => /^https?:\/\//i.test(w) || /zakupki\.gov\.ru/i.test(w));
  return words.length > 0 && urlWords.length / words.length > 0.7;
}

function onlyEmptyNumberColumns(text) {
  const s = String(text || '').trim();
  if (!/__EMPTY/i.test(s)) return false;
  const withoutLabels = s
    .replace(/Строка\s+\d+:/gi, '')
    .replace(/__EMPTY_?\d*\s*:/gi, '')
    .replace(/Приложение\s+к\s+заявке\s*:/gi, '')
    .replace(/[\s|:;,.-]/g, '')
    .trim();
  return /^\d+$/.test(withoutLabels);
}

function isUsefulSpreadsheetText(text) {
  const s = String(text || '').trim();
  if (s.length < 80) return false;
  if (isMostlyUrl(s)) return false;
  if (/^https?:\/\/\S+$/i.test(s)) return false;
  if (!/[а-яёa-z0-9]/i.test(s)) return false;
  if (onlyEmptyNumberColumns(s)) return false;
  return /(наименование|товар|работ|услуг|характеристик|кол-во|количество|ед\.?\s*изм|цена|стоимость|нмц|нмцд|нмцк|спецификац|поставка|предмет\s+закупки|форма\s*1|приложение|окпд|производител|страна\s+происхождения)/i.test(s);
}

function isUsefulText(text, route = '', ext = '') {
  const s = String(text || '').trim();

  const r = String(route || '').toLowerCase();
  const e = String(ext || '').toLowerCase();
  if (r === 'spreadsheet' || ['xls', 'xlsx', 'csv'].includes(e)) {
    return isUsefulSpreadsheetText(s);
  }

  if (s.length < 500) return false;
  if (isMostlyUrl(s)) return false;
  if (/^https?:\/\/\S+$/i.test(s)) return false;
  if (s.includes('zakupki.gov.ru/epz/order/notice') && s.length < 1000) return false;
  if (!/[а-яёa-z0-9]/i.test(s)) return false;

  return true;
}

function getTextFromParsedJson(j) {
  return String(
    j.parsedText ||
    j.text ||
    j.extractedText ||
    j.documentText ||
    j.content ||
    j.body ||
    j.markdown ||
    j.data ||
    j.result ||
    j.rawText ||
    j.output ||
    ''
  ).trim();
}

const parsedByIndex = new Map();

for (const item of parsedItems) {
  const j = item.json || {};
  const idx = Number(j.documentIndex || 0);
  if (!idx) continue;

  const candidateText = getTextFromParsedJson(j);
  const qualityOk = isUsefulText(candidateText, j.parserRoute, j.fileExtension);

  const parsed = {
    text: qualityOk ? candidateText : '',
    rawTextPreview: candidateText.slice(0, 500),
    rawTextLength: candidateText.length,
    textQualityOk: qualityOk,
    parserStatus: qualityOk ? 'ok' : (j.parserStatus || 'not_parsed_quality_failed'),
    parserError: j.parserError || j.error || j.message || '',
    parserWarning: qualityOk
      ? (j.parserWarning || '')
      : (j.parserWarning || ((String(j.parserRoute || '').toLowerCase() === 'spreadsheet' || ['xls','xlsx','csv'].includes(String(j.fileExtension || '').toLowerCase()))
          ? (onlyEmptyNumberColumns(candidateText)
              ? `Excel-файл содержит только техническую строку с номерами колонок (__EMPTY + номера), не добавлен в LLM.; rawTextLength=${candidateText.length}`
              : `Excel-файл содержит короткую шапку/инструкцию без явных товарных строк; не добавлен в LLM.; preview="${candidateText.slice(0, 160).replace(/\s+/g, ' ')}"; rawTextLength=${candidateText.length}`)
          : `Текст извлечён, но не прошёл quality check: длина ${candidateText.length}, preview="${candidateText.slice(0, 120).replace(/\s+/g, ' ')}"`))
  };

  const prev = parsedByIndex.get(idx);
  if (!prev || (parsed.text.length > (prev.text || '').length) || (!prev.text && parsed.rawTextLength > (prev.rawTextLength || 0))) {
    parsedByIndex.set(idx, parsed);
  }
}

const hasExtractedArchiveChildren = detectedItems.some(item => item.json?.extractedFromArchive);

const detectedForDocuments = detectedItems.filter((item) => {
  const j = item.json || {};
  const ext = String(j.fileExtension || '').toLowerCase();
  const route = String(j.parserRoute || '').toLowerCase();

  if (j.skipDocumentCollect) return false;

  // If an archive was successfully decompressed, do not count the archive itself as an unparsed document.
  if (hasExtractedArchiveChildren && !j.extractedFromArchive && (ext === 'zip' || ext === 'rar' || ext === '7z' || route === 'zip' || route === 'archive7z' || route === 'zip_unsupported' || route === 'archive_unsupported')) {
    return false;
  }

  return true;
});

const documents = detectedForDocuments.map((item, index) => {
  const j = item.json || {};
  const idx = Number(j.documentIndex || index + 1);
  const parsed = parsedByIndex.get(idx) || {};
  const text = parsed.text || '';
  const textLength = text.length;
  const ext = j.fileExtension || '';

  let parserStatus = parsed.parserStatus || 'not_parsed';
  let parserWarning = parsed.parserWarning || j.parserWarning || '';

  if (!text && !parserWarning) {
    parserWarning = 'Файл скачан, но parser-нода не вернула полезный текст.';
  }

  const rawName = j.documentFileName || j.fileName || j.filename || '';
  const fallbackName = j.extractedFromArchive
    ? `Файл из архива ${j.archiveChildIndex || idx}${ext ? '.' + ext : ''}`
    : '';

  return {
    documentIndex: idx,
    documentUrl: j.documentUrl || base.documentLinks?.[index] || '',
    fileName: fixMojibake(rawName, fallbackName),
    originalFileName: rawName && looksGarbled(rawName) ? rawName : undefined,
    fileExtension: ext,
    mimeType: j.mimeType || '',
    fileSize: j.fileSize || '',
    parserRoute: j.parserRoute || '',
    extractedFromArchive: Boolean(j.extractedFromArchive),
    parentArchiveFileName: j.parentArchiveFileName || '',
    text,
