function cleanCell(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim();
}

function isNoiseKey(key) {
  const k = String(key || '').toLowerCase();
  return k === 'row_number' || k === '__rownum__' || k === '__sheet__';
}

function rowToEntries(row) {
  return Object.entries(row || {})
    .filter(([k, v]) => !isNoiseKey(k) && v !== null && v !== undefined && cleanCell(v) !== '')
    .map(([k, v]) => `${k}: ${cleanCell(v)}`);
}

function rowToLine(row, idx) {
  const entries = rowToEntries(row);
  return entries.length ? `Строка ${idx + 1}: ${entries.join(' | ')}` : '';
}

function onlyEmptyNumberColumns(text) {
  const s = String(text || '').trim();
  if (!/__EMPTY/i.test(s)) return false;
  const withoutLabels = s
    .replace(/Строка\s+\d+:/gi, '')
    .replace(/__EMPTY_?\d*\s*:/gi, '')
    .replace(/Приложение\s+к\s+заявке\s*:/gi, '')
    .replace(/[\s|:;,.-]/g, '')
    .trim();
  return /^\d+$/.test(withoutLabels);
}

function isUsefulSpreadsheetText(text) {
  const s = String(text || '').trim();
  if (s.length < 80) return false;
  if (/^https?:\/\/\S+$/i.test(s)) return false;
  if (!/[а-яёa-z0-9]/i.test(s)) return false;

  // Отбрасываем строки, где фактически только __EMPTY + номера колонок.
  if (onlyEmptyNumberColumns(s)) return false;

  // Для Excel допускаем короткие, но смысловые таблицы/шапки.
  const usefulKeywords = /(наименование|товар|работ|услуг|характеристик|кол-во|количество|ед\.?\s*изм|цена|стоимость|нмц|нмцд|нмцк|спецификац|поставка|предмет\s+закупки|форма\s*1|приложение|окпд|производител|страна\s+происхождения)/i;
  return usefulKeywords.test(s);
}

function getPairIndex(item, fallback) {
  const p = item.pairedItem;
  if (Array.isArray(p) && p.length && Number.isInteger(p[0].item)) return p[0].item;
  if (p && Number.isInteger(p.item)) return p.item;
  return fallback;
}

function looksGarbled(name) {
  const s = String(name || '');
  return /[\u0080-\u009F]/.test(s) || /[]/.test(s);
}

function safeName(rawName, docIndex, ext) {
  const raw = String(rawName || '').trim();
  if (!raw || looksGarbled(raw)) return `Файл из архива ${docIndex || 'Excel'}${ext ? '.' + ext : ''}`;
  return raw;
}

let spreadsheetSources = [];
