const inputItems = $input.all();
const groups = new Map();

inputItems.forEach((item, idx) => {
  const row = item.json || {};
  const pairIndex = getPairIndex(item, idx);
  const docIndexFromRow = row.documentIndex || row.document_index || row.archiveDocumentIndex;
  const key = docIndexFromRow ? `doc_${docIndexFromRow}` : `pair_${pairIndex}`;
  if (!groups.has(key)) groups.set(key, { rows: [], pairIndex, firstJson: row });
  groups.get(key).rows.push(row);
});

let groupNo = 0;
const out = [];

for (const group of groups.values()) {
  const source =
    (group.firstJson && group.firstJson.documentIndex ? group.firstJson : null) ||
    spreadsheetSources.find(s => Number(s.documentIndex || -1) === Number(group.firstJson.documentIndex || -999999)) ||
    spreadsheetSources[group.pairIndex] ||
    spreadsheetSources[groupNo] ||
    {};

  const lines = [];
  const sheetNames = new Set();

  group.rows.forEach((row, idx) => {
    if (row.__sheet__) sheetNames.add(String(row.__sheet__));
    const line = rowToLine(row, idx);
    if (line) lines.push(line);
  });

  const header = [];
  if (sheetNames.size) header.push(`Листы: ${Array.from(sheetNames).join(', ')}`);
  header.push(`Всего строк Excel: ${group.rows.length}`);

  const text = [header.join('\n'), ...lines].filter(Boolean).join('\n');
  const ok = isUsefulSpreadsheetText(text);

  const ext = source.fileExtension || group.firstJson.fileExtension || 'xlsx';
  const docIndex = source.documentIndex || group.firstJson.documentIndex || groupNo + 1;
  const rawName = source.documentFileName || source.fileName || source.filename || group.firstJson.documentFileName || group.firstJson.fileName || '';
  const fileName = safeName(rawName, docIndex, ext);

  let warning = source.parserWarning || '';
  if (!ok) {
    const preview = text.slice(0, 160).replace(/\s+/g, ' ');
    if (onlyEmptyNumberColumns(text)) {
      warning = `Excel-файл содержит только техническую строку с номерами колонок (__EMPTY + номера), не добавлен в LLM.; rawTextLength=${text.length}`;
    } else if (text.length < 80) {
      warning = `Excel-файл дал слишком короткий текст (${text.length} символов), не добавлен в LLM.; preview="${preview}"`;
    } else {
      warning = `Excel-файл содержит короткую шапку/инструкцию без явных товарных строк; не добавлен в LLM.; preview="${preview}"; rawTextLength=${text.length}`;
    }
  }

  out.push({
    json: {
      ...source,
      documentIndex: docIndex,
      documentFileName: fileName,
      fileName,
      fileExtension: ext,
      mimeType: source.mimeType || group.firstJson.mimeType || '',
      fileSize: source.fileSize || group.firstJson.fileSize || '',
      parserRoute: 'spreadsheet',
      parsedText: text,
      text: ok ? text : '',
      rawTextLength: text.length,
      textLength: ok ? text.length : 0,
      textQualityOk: ok,
      textPreview: ok ? text.slice(0, 500) : '',
      rawTextPreview: text.slice(0, 500),
      excelRowsCount: group.rows.length,
      parserStatus: ok ? 'ok' : 'spreadsheet_quality_failed',
      parserError: '',
      parserWarning: warning
    },
    binary: group.firstJson.binary
  });
  groupNo += 1;
}

return out;

