function extensionFromName(name) {
  const clean = String(name || '').split('?')[0].split('#')[0];
  const m = clean.match(/\.([a-z0-9]{2,5})$/i);
  return m ? m[1].toLowerCase() : '';
}

function extensionFromMime(mime) {
  const m = String(mime || '').toLowerCase();
  if (m.includes('pdf')) return 'pdf';
  if (m.includes('wordprocessingml')) return 'docx';
  if (m.includes('msword')) return 'doc';
  if (m.includes('spreadsheetml')) return 'xlsx';
  if (m.includes('vnd.ms-excel')) return 'xls';
  if (m.includes('excel')) return 'xlsx';
  if (m.includes('zip')) return 'zip';
  if (m.includes('rar')) return 'rar';
  if (m.includes('7z') || m.includes('x-7z-compressed')) return '7z';
  return '';
}

function looksGarbled(name) {
  const s = String(name || '');
  // Typical archive mojibake for Russian file names contains C1 controls or odd CP866-looking sequences.
  return /[\u0080-\u009F]/.test(s) || /[]/.test(s);
}

function safeFileName(rawName, child, ext) {
  const raw = String(rawName || '').trim();
  if (!raw || looksGarbled(raw)) return `Файл из архива ${child}${ext ? '.' + ext : ''}`;
  return raw;
}

const output = [];
const parentItems = $input.all();

for (const item of parentItems) {
  const parent = item.json || {};
  const bin = item.binary || {};
  let child = 0;

  for (const key of Object.keys(bin)) {
    const b = bin[key];
    if (!b) continue;

    child += 1;
    const rawFileName = b.fileName || b.filename || `archive_file_${child}`;
    const ext =
      b.fileExtension ||
      extensionFromName(rawFileName) ||
      extensionFromMime(b.mimeType || '') ||
      extensionFromName(b.id || '') ||
      '';
    const fileName = safeFileName(rawFileName, child, ext);

    output.push({
      json: {
        ...parent,
        parentArchiveUrl: parent.documentUrl || '',
        parentArchiveFileName: parent.documentFileName || parent.fileName || '',
        originalArchiveFileName: rawFileName,
        documentUrl: parent.documentUrl || '',
        documentFileName: fileName,
        fileName,
        fileExtension: ext,
        mimeType: b.mimeType || parent.mimeType || '',
        fileSize: b.fileSize || parent.fileSize || '',
        documentIndex: Number(parent.documentIndex || 0) * 1000 + child,
        archiveChildIndex: child,
        extractedFromArchive: true,
        skipDocumentCollect: false,
        parserWarning: looksGarbled(rawFileName)
          ? `Имя файла в архиве было в неверной кодировке, использовано безопасное имя: ${fileName}. Оригинал: ${rawFileName}`
          : ''
      },
      // Normalize every extracted file to binary property `data`, because parser nodes expect it.
      binary: { data: b }
    });
  }

  if (!child) {
    output.push({
      json: {
        ...parent,
        parsedText: '',
        text: '',
        parserStatus: 'archive_empty_or_failed',
        parserWarning: parent.parserWarning || `Архив ${parent.fileExtension || parent.parserRoute || ''} найден, но нода распаковки не вернула вложенные файлы. Возможно архив защищён, повреждён или не поддерживается текущей нодой.`,
        parserError: parent.error || parent.message || '',
        skipDocumentCollect: false
      },
      binary: item.binary
    });
  }
}

return output;

function fixMojibake(value) {
  const s = String(value || '');
  if (!s) return '';
  if (/[ÐÑ]/.test(s)) {
    try { return Buffer.from(s, 'latin1').toString('utf8'); } catch {}
  }
  return s;
}

function extensionFromName(name) {
  const clean = String(name || '').split('?')[0].split('#')[0];
  const m = clean.match(/\.([a-z0-9]{2,5})$/i);
  return m ? m[1].toLowerCase() : '';
}

function extensionFromMime(mime) {
  const m = String(mime || '').toLowerCase();

  if (m.includes('pdf')) return 'pdf';
  if (m.includes('wordprocessingml')) return 'docx';
  if (m.includes('msword')) return 'doc';
  if (m.includes('spreadsheetml')) return 'xlsx';
  if (m.includes('vnd.ms-excel')) return 'xls';
  if (m.includes('excel')) return 'xlsx';
  if (m.includes('zip')) return 'zip';
  if (m.includes('rar')) return 'rar';
  if (m.includes('7z') || m.includes('x-7z-compressed')) return '7z';

  return '';
}

function extensionFromBinaryMeta(binary) {
  const b = binary || {};
  return (
    extensionFromName(b.fileName || b.filename || '') ||
    extensionFromName(b.id || b.fileId || '') ||
    extensionFromMime(b.mimeType || '')
  );
}

function parserRoute(ext) {
  if (ext === 'docx') return 'docx_xml';
  if (ext === 'doc') return 'doc_rebuild';
  if (ext === 'pdf') return 'pdf';
  if (ext === 'xlsx' || ext === 'xls' || ext === 'csv') return 'spreadsheet';

  // Вложенные архивы пока не раскрываем рекурсивно:
  // Switch Extracted Parser Route9 отправит их в unsupported.
  if (ext === 'zip' || ext === 'rar' || ext === '7z') return 'nested_archive';

  return 'unknown';
}

return $input.all().map((item, i) => {
  const j = item.json || {};
  const b = item.binary?.data || {};

  // Для извлечённых файлов также доверяем сначала фактическому binary.fileName.
  const binaryFileName = fixMojibake(
    b.fileName || b.filename || ''
  );

  const declaredFileName = fixMojibake(
    j.documentFileName || j.fileName || j.filename || ''
  );

  const binaryExt = extensionFromName(binaryFileName);
  const declaredExt = extensionFromName(declaredFileName);
  const mimeExt = extensionFromMime(b.mimeType || j.mimeType || '');
  const binaryMetaExt = extensionFromBinaryMeta(b);

  const ext =
    binaryExt ||
    declaredExt ||
    mimeExt ||
    binaryMetaExt ||
    'unknown';

  const route = parserRoute(ext);
  const fileName = binaryFileName || declaredFileName || `archive_file_${i + 1}.${ext}`;
  const mimeType = b.mimeType || j.mimeType || '';
  const fileSize = b.fileSize || j.fileSize || '';

  const warning =
