function evidence(regex, radius = 180) {
  const match = allText.match(regex);

  if (!match) {
    return '';
  }

  const index = match.index || 0;

  return allText
    .slice(
      Math.max(0, index - radius),
      Math.min(allText.length, index + radius)
    )
    .replace(/\s+/g, ' ')
    .trim();
}

function money(value) {
  const text = String(value || '')
    .replace(/\u00a0/g, ' ')
    .toLowerCase();

  const match = text.match(/([\d\s]+(?:[,.]\d+)?)/);

  if (!match) {
    return null;
  }

  let number = Number(
    match[1]
      .replace(/\s/g, '')
      .replace(',', '.')
  );

  if (!Number.isFinite(number)) {
    return null;
  }

  if (/млрд/.test(text)) {
    number *= 1_000_000_000;
  } else if (/млн/.test(text)) {
    number *= 1_000_000;
  } else if (/тыс/.test(text)) {
    number *= 1_000;
  }

  return number;
}

function dateInMoscow() {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Moscow',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(new Date());

  const result = Object.fromEntries(
    parts.map(part => [part.type, part.value])
  );

  return `${result.year}-${result.month}-${result.day}`;
}

function businessDaysInclusive(startString, endString) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(endString || '')) {
    return null;
  }

  const start = new Date(`${startString}T00:00:00Z`);
  const end = new Date(`${endString}T00:00:00Z`);

  if (
    Number.isNaN(start.getTime()) ||
    Number.isNaN(end.getTime())
  ) {
    return null;
  }

  if (end < start) {
    return 0;
  }

  let count = 0;

  for (
    let date = new Date(start);
    date <= end;
    date.setUTCDate(date.getUTCDate() + 1)
  ) {
    const weekDay = date.getUTCDay();

    if (weekDay !== 0 && weekDay !== 6) {
      count += 1;
    }
  }

  return count;
}

/**
 * Приводит дату к объекту Date.
 *
 * Поддерживаемые форматы:
 * - YYYY-MM-DD
 * - DD.MM.YYYY
 * - DD.MM.YY
 */
function normalizeDateValue(value) {
  if (!value) {
    return null;
  }

  let rawValue = value;

  if (
    typeof rawValue === 'object' &&
    rawValue !== null &&
    'value' in rawValue
  ) {
    rawValue = rawValue.value;
  }

  const text = String(rawValue || '').trim();

  if (!text) {
    return null;
  }

  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    const date = new Date(`${text}T00:00:00Z`);

    return Number.isNaN(date.getTime())
      ? null
      : date;
  }

  let match = text.match(
    /\b(\d{1,2})\.(\d{1,2})\.(\d{4})\b/
  );

  if (match) {
    const iso = [
      match[3],
      match[2].padStart(2, '0'),
      match[1].padStart(2, '0')
    ].join('-');

    const date = new Date(`${iso}T00:00:00Z`);

    return Number.isNaN(date.getTime())
      ? null
      : date;
  }

  match = text.match(
    /\b(\d{1,2})\.(\d{1,2})\.(\d{2})\b/
  );

  if (match) {
    const shortYear = Number(match[3]);

    const year = shortYear >= 70
      ? 1900 + shortYear
      : 2000 + shortYear;

    const iso = [
      year,
      match[2].padStart(2, '0'),
      match[1].padStart(2, '0')
    ].join('-');

    const date = new Date(`${iso}T00:00:00Z`);

    return Number.isNaN(date.getTime())
      ? null
      : date;
  }

  const russianMonthMatch = text.match(
    /\b(\d{1,2})\s+(января|февраля|марта|апреля|мая|июня|июля|августа|сентября|октября|ноября|декабря)\s+(\d{4})\b/i
  );

  if (russianMonthMatch) {
    const months = {
      января: '01',
      февраля: '02',
      марта: '03',
      апреля: '04',
      мая: '05',
      июня: '06',
      июля: '07',
      августа: '08',
      сентября: '09',
      октября: '10',
      ноября: '11',
      декабря: '12'
    };

    const iso = [
      russianMonthMatch[3],
      months[russianMonthMatch[2].toLowerCase()],
      russianMonthMatch[1].padStart(2, '0')
    ].join('-');

    const date = new Date(`${iso}T00:00:00Z`);

    return Number.isNaN(date.getTime())
      ? null
      : date;
  }

  return null;
}

function formatDateRu(date) {
  if (
    !(date instanceof Date) ||
    Number.isNaN(date.getTime())
  ) {
    return '';
  }

  return [
    String(date.getUTCDate()).padStart(2, '0'),
    String(date.getUTCMonth() + 1).padStart(2, '0'),
    date.getUTCFullYear()
  ].join('.');
}

/**
 * Добавляет календарные месяцы.
 * Корректно обрабатывает последние числа месяца.
 */
function addCalendarMonths(date, months) {
  const result = new Date(date.getTime());
  const originalDay = result.getUTCDate();

  result.setUTCDate(1);
  result.setUTCMonth(result.getUTCMonth() + months);

  const lastDayOfTargetMonth = new Date(
    Date.UTC(
      result.getUTCFullYear(),
      result.getUTCMonth() + 1,
      0
    )
  ).getUTCDate();

  result.setUTCDate(
    Math.min(originalDay, lastDayOfTargetMonth)
  );

  return result;
}

function calendarMonthsBetween(start, end) {
  let months =
    (
      end.getUTCFullYear() -
      start.getUTCFullYear()
    ) * 12 +
    (
      end.getUTCMonth() -
      start.getUTCMonth()
    );

  if (end.getUTCDate() < start.getUTCDate()) {
    months -= 1;
  }

  return months;
}

function calendarDaysBetween(start, end) {
  const milliseconds =
    end.getTime() -
    start.getTime();

  return Math.floor(
    milliseconds / (24 * 60 * 60 * 1000)
  );
}

/**
 * Определяет конечную дату поставки.
 *
 * Приоритет:
 * 1. fields.deliveryDate;
 * 2. конкретная дата в документации;
 * 3. deliveryDays от даты заведения.
 */
function findDeliveryDate(fieldsObject, text, createdDate) {
  const structuredDate = normalizeDateValue(
    fieldsObject.deliveryDate
  );

  if (structuredDate) {
    return {
      date: structuredDate,
      source: 'fields.deliveryDate',
      evidence: `Дата поставки: ${fieldsObject.deliveryDate}`
    };
  }

  const patterns = [
    /(?:срок\s+поставки|дата\s+поставки|поставка\s+товара)[\s\S]{0,160}?(?:до|не\s+позднее)\s+(\d{1,2}\.\d{1,2}\.\d{2,4})/i,

    /(?:поставк[а-я]*|поставить|передать\s+товар)[\s\S]{0,160}?(?:до|не\s+позднее)\s+(\d{1,2}\.\d{1,2}\.\d{2,4})/i,

    /(?:срок\s+поставки|дата\s+поставки|поставка\s+товара)[\s\S]{0,160}?(?:до|не\s+позднее)\s+(\d{4}-\d{2}-\d{2})/i,

    /(?:поставк[а-я]*|поставить|передать\s+товар)[\s\S]{0,160}?(?:до|не\s+позднее)\s+(\d{4}-\d{2}-\d{2})/i,

    /(?:срок\s+поставки|поставка\s+товара)[\s\S]{0,160}?(?:до|не\s+позднее)\s+(\d{1,2}\s+(?:января|февраля|марта|апреля|мая|июня|июля|августа|сентября|октября|ноября|декабря)\s+\d{4})/i
  ];

  for (const pattern of patterns) {
    const match = String(text || '').match(pattern);

    if (!match?.[1]) {
      continue;
    }

    const parsedDate = normalizeDateValue(match[1]);

    if (!parsedDate) {
      continue;
    }

    const index = match.index || 0;

    return {
      date: parsedDate,
      source: 'Текст документации',
      evidence: String(text)
        .slice(
          Math.max(0, index - 100),
          Math.min(
            String(text).length,
            index + match[0].length + 180
          )
        )
        .replace(/\s+/g, ' ')
        .trim()
    };
  }

  const deliveryDaysValue = Number(
    String(
      fieldsObject.deliveryDays ||
      ''
    )
      .replace(',', '.')
      .match(/\d+(?:\.\d+)?/)?.[0] ||
    ''
  );

  if (
    createdDate &&
    Number.isFinite(deliveryDaysValue) &&
    deliveryDaysValue > 0
  ) {
    const calculatedDate = new Date(
      createdDate.getTime()
    );

    calculatedDate.setUTCDate(
      calculatedDate.getUTCDate() +
      Math.ceil(deliveryDaysValue)
    );

    return {
      date: calculatedDate,
      source: 'fields.deliveryDays',
      evidence:
        `Дата поставки рассчитана по сроку ` +
        `${deliveryDaysValue} календарных дней ` +
        `от даты заведения тендера.`
    };
  }

  return null;
}

