  const dayType = match[2].toLowerCase();

  const tooManyWorkingDays =
    dayType.startsWith('рабоч') &&
    numberOfDays > 120;

  const tooManyCalendarDays =
    dayType.startsWith('календарн') &&
    numberOfDays > 180;

  if (
    tooManyWorkingDays ||
    tooManyCalendarDays
