    const index = match.index || 0;

    const voltageEvidence = allText
      .slice(
        Math.max(0, index - 180),
        Math.min(allText.length, index + 220)
      )
      .replace(/\s+/g, ' ')
      .trim();

    add(
      'Номенклатура. Оборудование 35 кВ и выше',
      `Обнаружено напряжение ${voltage} кВ. ${voltageEvidence}`,
      55
    );

    break;
  }
}

