function findWorksEvidence(text) {
  const positivePatterns = [
    /поставк[а-я]*[\s\S]{0,100}(?:с\s+монтажом|с\s+установкой|с\s+пусконаладк|с\s+вводом\s+в\s+эксплуатацию)/ig,

    /(?:выполнить|выполнение|проведение|оказание)[\s\S]{0,80}(?:монтажн[а-я]*|пусконаладочн[а-я]*|строительно[-\s]монтажн[а-я]*|подрядн[а-я]*)\s+работ/ig,

    /(?:монтаж|установк[а-я]*|пусконаладк[а-я]*|ввод\s+в\s+эксплуатацию)[\s\S]{0,100}(?:поставщиком|подрядчиком|силами\s+поставщика|входит\s+в\s+(?:предмет|стоимость|объ[её]м))/ig,

    /шеф[-\s]?монтажн[а-я]*\s+работ|пусконаладочн[а-я]*\s+работ|строительно[-\s]монтажн[а-я]*\s+работ/ig
  ];

  const negativePattern =
    /(?:монтаж|установк[а-я]*|пусконаладк[а-я]*|работ[а-я]*)[\s\S]{0,70}(?:не\s+требуется|не\s+предусмотрен[аоы]?|не\s+входит|выполняется\s+заказчиком|силами\s+заказчика|без\s+монтаж)/i;

  for (const pattern of positivePatterns) {
    pattern.lastIndex = 0;

    const match = pattern.exec(text);

    if (!match) {
      continue;
    }

    const index = match.index || 0;

    const snippet = text
      .slice(
        Math.max(0, index - 180),
        Math.min(
          text.length,
          index + Math.max(
            260,
            match[0].length + 180
          )
        )
      )
      .replace(/\s+/g, ' ')
      .trim();

    if (!negativePattern.test(snippet)) {
      return snippet;
    }
  }

  return '';
}

