1. Приоритет имеет фактический получатель поставки: "Грузополучатель", "Получатель", "Заказчик", "Покупатель", филиал заказчика.
2. Если в реквизитах указана головная компания и отдельно указан филиал, а поставка или заказчик относится к филиалу, выбирай филиал.
3. У филиалов часто ИНН совпадает с головной компанией, а КПП отличается. Если в одном блоке реквизитов указан ИНН головной компании, а рядом указан филиал и его КПП, можно выбрать ИНН головной компании + КПП филиала.
4. Особенно внимательно проверяй разделы договора: "Реквизиты и подписи сторон", "Адреса и банковские реквизиты сторон", "Юридические адреса и реквизиты сторон", пункты 9, 16, 19.
5. Если на странице тендера/Seldon указан "Заказчик" как филиал, это сильный сигнал, что нужен именно филиал, но ИНН/КПП всё равно надо брать только из найденных данных.
6. Не выбирай реквизиты поставщика, исполнителя, подрядчика, банка, УФК, казначейства, грузоотправителя.
7. Не выдумывай ИНН/КПП. Если не найдено — верни null для отсутствующего поля.
8. Если в документах нет подходящего фактического заказчика/филиала/грузополучателя, используй fallback из Seldon/Daily. Это исходные значения, уже пришедшие в workflow из Seldon или из ежедневной строки Daily.

Приоритет источников:
1. Договор / проект договора / контракт / спецификация.
2. Техническое задание / описание предмета закупки.
3. Извещение.
4. Страница тендера / структурированные данные Seldon.
5. Fallback из Seldon/Daily.

Верни схему:
{
  "selected": true,
  "source": "document_consignee|document_branch_requisites|document_customer|tender_page_customer|seldon_fallback|not_found",
  "selectedRole": "Грузополучатель|Получатель|Филиал|Заказчик|Покупатель|Организатор|fallback",
  "actualCustomerName": "string|null",
  "actualCustomerInn": "10 или 12 цифр|null",
  "actualCustomerKpp": "9 цифр|null",
  "replaceInputInn": true,
  "replaceInputKpp": true,
  "confidence": "low|medium|high",
  "evidence": "короткая цитата, подтверждающая выбор",
  "warnings": []
}

Входные данные:
${JSON.stringify(candidateContext, null, 2)}`;

const logs = [...(source.logs || [])];
logs.push({
  time: new Date().toISOString(),
  step: 'Подготовка кандидатов фактического заказчика',
  status: 'ok',
  details: `Найдено кандидатов: ${candidates.length}; передано агенту: ${topCandidates.length}.`
});

return [{
  json: {
    ...source,
    actualCustomerCandidates: topCandidates,
    actualCustomerCandidateContext: candidateContext,
    actualCustomerPrompt,
    logs,
  }
}];

const source = $('Extract Actual Customer Candidates').first().json || $json || {};

function getAgentContent(j) {
  if (!j) return '';
  if (typeof j.output === 'string') return j.output;
  if (typeof j.text === 'string') return j.text;
  if (typeof j.response === 'string') return j.response;
  if (typeof j.content === 'string') return j.content;
  if (typeof j.message === 'string') return j.message;
  if (j.data && typeof j.data === 'string') return j.data;
  const c = j.choices?.[0]?.message?.content || j.body?.choices?.[0]?.message?.content;
  if (typeof c === 'string') return c;
  return '';
}
function extractJson(text) {
  const s = String(text || '').trim();
  if (!s) return null;
  try { return JSON.parse(s); } catch {}
  const fenced = s.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fenced?.[1]) { try { return JSON.parse(fenced[1].trim()); } catch {} }
  const first = s.indexOf('{'); const last = s.lastIndexOf('}');
  if (first >= 0 && last > first) { try { return JSON.parse(s.slice(first, last + 1)); } catch {} }
  return null;
}
function clean(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}
function digits(value) {
  return String(value ?? '').replace(/\D/g, '');
}
function validInn(value) {
  const d = digits(value);
  return /^(\d{10}|\d{12})$/.test(d) ? d : '';
}
function validKpp(value) {
  const d = digits(value);
  return /^\d{9}$/.test(d) ? d : '';
}
function confidence(value) {
  const s = String(value || '').toLowerCase();
  return ['low', 'medium', 'high'].includes(s) ? s : 'low';
}
function setMeta(meta, key, sourceName, conf, evidence) {
  meta[key] = {
    source: sourceName || 'Resolve Actual Customer',
    confidence: confidence(conf),
    evidence: clean(evidence).slice(0, 900),
  };
}

const fields = { ...(source.fields || {}) };
const meta = { ...(source.meta || {}) };
const warnings = [...(source.warnings || [])];
const logs = [...(source.logs || [])];
const debug = { ...(source.debug || {}) };

const rawContent = getAgentContent($json);
let resolution = extractJson(rawContent);

if (!resolution || typeof resolution !== 'object') {
  resolution = {
    selected: false,
    source: 'not_found',
    selectedRole: 'fallback',
    actualCustomerName: null,
    actualCustomerInn: null,
    actualCustomerKpp: null,
    replaceInputInn: false,
    replaceInputKpp: false,
    confidence: 'low',
    evidence: '',
    warnings: ['AI Agent - Resolve Actual Customer не вернул валидный JSON. Значения контрагента оставлены без изменений.'],
  };
  warnings.push('AI Agent - Resolve Actual Customer не вернул валидный JSON. Значения контрагента оставлены без изменений.');
}

const inputBefore = {
  name: fields.counterpartyName || null,
  inn: validInn(fields.counterpartyInn || fields.inn) || null,
  kpp: validKpp(fields.counterpartyKpp || fields.kpp) || null,
};

const finalName = clean(resolution.actualCustomerName);
const finalInn = validInn(resolution.actualCustomerInn);
const finalKpp = validKpp(resolution.actualCustomerKpp);
const sourceName = `Resolve Actual Customer: ${resolution.source || 'not_found'} / ${resolution.selectedRole || ''}`;
const evidence = resolution.evidence || '';

let changed = false;

if (finalName) {
  fields.counterpartyName = finalName;
  setMeta(meta, 'counterpartyName', sourceName, resolution.confidence, evidence);
  changed = true;
}

if (finalInn && (resolution.replaceInputInn !== false || !inputBefore.inn || finalInn !== inputBefore.inn)) {
  fields.counterpartyInn = finalInn;
  setMeta(meta, 'counterpartyInn', sourceName, resolution.confidence, evidence);
  changed = true;
}

if (finalKpp && (resolution.replaceInputKpp !== false || !inputBefore.kpp || finalKpp !== inputBefore.kpp)) {
  fields.counterpartyKpp = finalKpp;
  setMeta(meta, 'counterpartyKpp', sourceName, resolution.confidence, evidence);
  changed = true;
}

// Совместимые aliases для последующих нод и CRM.
if (fields.counterpartyName) fields.counterparty = fields.counterpartyName;
if (fields.counterpartyInn) fields.inn = fields.counterpartyInn;
if (fields.counterpartyKpp) fields.kpp = fields.counterpartyKpp;

const finalAfter = {
  name: fields.counterpartyName || null,
  inn: validInn(fields.counterpartyInn || fields.inn) || null,
  kpp: validKpp(fields.counterpartyKpp || fields.kpp) || null,
};

if (finalAfter.inn && inputBefore.inn && finalAfter.inn !== inputBefore.inn) {
  warnings.push(`ИНН из исходных данных ${inputBefore.inn} заменён на ${finalAfter.inn}. Источник: ${resolution.source || 'не указан'}.`);
}
if (finalAfter.kpp && inputBefore.kpp && finalAfter.kpp !== inputBefore.kpp) {
  warnings.push(`КПП из исходных данных ${inputBefore.kpp} заменён на ${finalAfter.kpp}. Источник: ${resolution.source || 'не указан'}.`);
}
for (const warning of Array.isArray(resolution.warnings) ? resolution.warnings : []) {
  if (warning) warnings.push(String(warning));
}

debug.actualCustomerResolution = {
  inputBefore,
  finalAfter,
  changed,
  selected: resolution.selected === true,
  source: resolution.source || 'not_found',
  selectedRole: resolution.selectedRole || null,
  confidence: confidence(resolution.confidence),
  evidence: clean(evidence).slice(0, 1200),
  candidatesCount: Array.isArray(source.actualCustomerCandidates) ? source.actualCustomerCandidates.length : 0,
  raw: resolution,
};

// Старый debug по отдельному КПП грузополучателя больше не используется.
delete debug.counterpartyKppResolution;

logs.push({
  time: new Date().toISOString(),
  step: 'Определение фактического заказчика / ИНН-КПП',
  status: changed ? 'ok' : 'no_change',
  details: changed
    ? `Итоговый контрагент: ${finalAfter.name || 'без названия'}, ИНН=${finalAfter.inn || 'нет'}, КПП=${finalAfter.kpp || 'нет'}.`
    : 'Фактический заказчик не изменил исходные значения; оставлен fallback/текущее значение.'
});

return [{
  json: {
    ...source,
    fields,
    meta,
    warnings: [...new Set(warnings.map(String))],
    logs,
    debug,
    actualCustomerResolution: debug.actualCustomerResolution,
    actualCustomerRaw: resolution,
  }
}];

const original = (() => {
  // Сначала используем item linking текущей итерации.
  try {
    return $('Prepare Combined Text for LLM2').item.json || {};
  } catch {}

  // Fallback для одиночного запуска.
  try {
    return $('Prepare Combined Text for LLM2').first().json || {};
  } catch {
    return {};
  }
})();

const agentResult = $json || {};

function firstDefined(...values) {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return value;
    }
  }
  return null;
}

function parseRemainingDays(value) {
  let raw = value;

  if (
    raw &&
    typeof raw === 'object' &&
    !Array.isArray(raw) &&
    'value' in raw
  ) {
    raw = raw.value;
  }

  const match = String(raw ?? '')
    .replace(',', '.')
    .match(/-?\d+(?:\.\d+)?/);

  if (!match) {
    return null;
  }

  const number = Number(match[0]);

  return Number.isFinite(number)
    ? number
    : null;
}

function codeFromText(text, keys) {
  const source = String(text || '');

  for (const key of keys) {
    const escaped = key.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const match = source.match(
      new RegExp(`["']${escaped}["']\\s*:\\s*["']([^"']+)["']`, 'i')
    );

    if (match?.[1] && String(match[1]).trim()) {
      return String(match[1]).trim();
    }
  }

  return null;
}

const embeddedToCode = firstDefined(
  codeFromText(original.pageText, ['toCode', 'Код ТО']),
  codeFromText(original.combinedText, ['toCode', 'Код ТО'])
);

const embeddedLawCode = firstDefined(
  codeFromText(original.pageText, ['lawCode', 'Код ФЗ']),
  codeFromText(original.combinedText, ['lawCode', 'Код ФЗ'])
);

const toCode = firstDefined(
  original.toCode,
  original['Код ТО'],
  original.reportFields?.['Код ТО'],
  original.seldonPurchase?.toCode,
  embeddedToCode
);

const lawCode = firstDefined(
  original.lawCode,
  original['Код ФЗ'],
  original.reportFields?.['Код ФЗ'],
  original.seldonPurchase?.lawCode,
  embeddedLawCode
);

const remainingDaysRaw = firstDefined(
  original.remainingDays,
  original.remainingDaysRaw,
  original['Осталось дней'],
  original.reportFields?.['Осталось дней'],
  original.seldonPurchase?.remainingBusinessDays
);

const remainingDays =
  parseRemainingDays(remainingDaysRaw);

const reportFields =
  original.reportFields &&
  typeof original.reportFields === 'object' &&
  !Array.isArray(original.reportFields)
    ? { ...original.reportFields }
    : {};

if (toCode !== null) {
  reportFields['Код ТО'] = String(toCode).trim();
}

if (lawCode !== null) {
  reportFields['Код ФЗ'] = String(lawCode).trim();
}

if (remainingDays !== null) {
  reportFields['Осталось дней'] =
    String(remainingDays);
}

return [{
  json: {
    ...original,

    // Сохраняем стандартные поля ответа AI Agent:
    // output/text/response и т. д., чтобы Validate Fields2 мог распарсить JSON модели.
    ...agentResult,

    // Код ТО не определяется моделью. Он детерминированно возвращается
    // из входного пакета Seldon filters сразу после AI Agent.
    toCode: toCode === null ? null : String(toCode).trim(),
    lawCode: lawCode === null ? null : String(lawCode).trim(),

    remainingDays,
    remainingDaysRaw:
      remainingDaysRaw ?? null,

    reportFields,

    contextRestoredAfterTenderFieldsAgent: true,
    contextRestoreDiagnostics: {
      directToCode: original.toCode ?? null,
      reportFieldsToCode: original.reportFields?.['Код ТО'] ?? null,
      purchaseToCode: original.seldonPurchase?.toCode ?? null,
      pageTextToCode: embeddedToCode,
      resolvedToCode: toCode,
      directRemainingDays:
        original.remainingDays ?? null,
      reportFieldsRemainingDays:
        original.reportFields?.['Осталось дней'] ?? null,
      resolvedRemainingDays:
        remainingDays
    },
    tenderFieldsAgentRaw: agentResult
  }
}];

const row = $input.first().json || {};

let payload = row.payload;

if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch {
    payload = {};
  }
}

if (
  !payload ||
  typeof payload !== 'object' ||
  Array.isArray(payload)
) {
  payload = {};
}

const jobRecordKey =
  row.jobRecordKey ||
  payload.jobRecordKey ||
  payload.recordKey ||
  null;

const asyncJobMarked =
  row.asyncJobMarked === true;

// Для обычного webhook/form запуска jobRecordKey отсутствует:
// такой запуск сохраняет прежнее поведение.
//
// Для async запуска ключ есть. Если Controller не оставил job
// в статусе dispatching, второй execution прекращается здесь.
if (
  jobRecordKey &&
  !asyncJobMarked
) {
  return [];
}

return [
  {
    json: {
      ...payload,
      jobRecordKey,
      asyncJobMarked
    }
  }
];

const row = $input.first().json || {};

let payload = row.payload;

if (typeof payload === 'string') {
  try {
    payload = JSON.parse(payload);
  } catch {
    payload = {};
  }
}

if (
  !payload ||
  typeof payload !== 'object' ||
  Array.isArray(payload)
) {
  payload = {};
}

return [
  {
    json: {
      ...payload,
      asyncJobCompleted:
        row.asyncJobCompleted === true
    }
  }
];

parameters.content:
## Tender Worker с контролируемым окном

Жизненный цикл одной job:

`queued → dispatching → processing → completed`

Controller запускает максимум 10 jobs одновременно.

В начале Worker:
- разрешает запуск только из `dispatching`;
- ставит `processing`;
- сохраняет execution ID.

В конце Worker:
- сохраняет `result_json`;
- ставит `completed`;
- освобождает слот для следующей job.

При аварийном падении job останется `processing`; Controller/Finalizer переведёт её в `failed` по тайм-ауту.

