function decodeXmlEntities(text) {
  return String(text || '')
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) =>
      String.fromCodePoint(parseInt(hex, 16))
    )
    .replace(/&#(\d+);/g, (_, dec) =>
      String.fromCodePoint(parseInt(dec, 10))
    )
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'");
}

function normalizeWordXml(xml) {
  return decodeXmlEntities(
    String(xml || '')
      // Сначала сохраняем логические разделители Word.
      .replace(/<w:tab\b[^>]*\/>/gi, '\t')
      .replace(/<w:br\b[^>]*\/>/gi, '\n')
      .replace(/<w:cr\b[^>]*\/>/gi, '\n')
      .replace(/<\/w:p>/gi, '\n')
      .replace(/<\/w:tr>/gi, '\n')
      .replace(/<\/w:tc>/gi, '\t')
      // Удаляем XML-теги, оставляя текст узлов w:t.
      .replace(/<[^>]+>/g, '')
  )
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\t{2,}/g, '\t')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function fullBinaryPath(key, binary) {
  const directory = String(binary?.directory || '')
    .replace(/\\/g, '/')
    .replace(/^\/+|\/+$/g, '');

  const fileName = String(
    binary?.fileName ||
    binary?.filename ||
    ''
  )
    .replace(/\\/g, '/')
    .replace(/^\/+/, '');

  return [directory, fileName, key]
    .filter(Boolean)
    .join('/')
    .replace(/\/+/g, '/');
}

const inputItems = $input.all();
const output = [];

for (let itemIndex = 0; itemIndex < inputItems.length; itemIndex++) {
  const item = inputItems[itemIndex];
  const source = item.json || {};
  const binaries = item.binary || {};

  let documentXmlKey = null;
  let documentXmlPath = null;

  for (const [key, binary] of Object.entries(binaries)) {
    const candidatePath = fullBinaryPath(key, binary);

    if (
      /(^|\/)word\/document\.xml$/i.test(candidatePath) ||
      /(^|[\/_-])word[\/_-]document\.xml$/i.test(String(key))
    ) {
      documentXmlKey = key;
      documentXmlPath = candidatePath;
      break;
    }
  }

  if (!documentXmlKey) {
    output.push({
      json: {
        ...source,
        cv_text: '',
        parsedText: '',
        parserStatus: 'docx_document_xml_not_found',
        parserError: '',
        parserWarning: [
          source.parserWarning,
          'DOCX распакован, но word/document.xml не найден. Файл передан дальше без текста.'
        ].filter(Boolean).join(' '),
        docxXmlFallbackUsed: true,
        docxXmlPath: null,
        skipDocumentCollect: false
      },
      pairedItem: { item: itemIndex }
    });
    continue;
  }

  try {
    const buffer = await this.helpers.getBinaryDataBuffer(
      itemIndex,
      documentXmlKey
    );

    const xml = buffer.toString('utf8');
    const text = normalizeWordXml(xml);

    output.push({
      json: {
        ...source,
        // Normalize Word Text2 найдёт cv_text и приведёт результат
        // к общему формату parsedText.
        cv_text: text,
        docxXmlFallbackUsed: true,
        docxXmlPath: documentXmlPath,
        docxXmlLength: xml.length,
        docxXmlTextLength: text.length,
        parserStatus: text ? 'docx_xml_extracted' : 'docx_xml_empty',
        parserError: '',
        parserWarning: [
          source.parserWarning,
          text
            ? 'Извлечённый из архива DOCX прочитан напрямую из word/document.xml.'
            : 'word/document.xml найден, но полезный текст не извлечён.'
        ].filter(Boolean).join(' '),
        skipDocumentCollect: false
      },
      pairedItem: { item: itemIndex }
    });
  } catch (error) {
    output.push({
      json: {
        ...source,
        cv_text: '',
        parsedText: '',
        parserStatus: 'docx_xml_read_error',
        parserError: String(error?.message || error || ''),
        parserWarning: [
          source.parserWarning,
          'Не удалось прочитать word/document.xml из DOCX.'
        ].filter(Boolean).join(' '),
        docxXmlFallbackUsed: true,
        docxXmlPath: documentXmlPath,
        skipDocumentCollect: false
      },
      pairedItem: { item: itemIndex }
    });
  }
}

return output;

const items = $input.all();
const output = [];

function detectMagic(buffer) {
  if (!Buffer.isBuffer(buffer) || buffer.length < 4) return 'unknown';

  // Старый бинарный Word DOC (OLE Compound File).
  if (
    buffer.length >= 8 &&
    buffer[0] === 0xD0 &&
    buffer[1] === 0xCF &&
    buffer[2] === 0x11 &&
    buffer[3] === 0xE0 &&
    buffer[4] === 0xA1 &&
    buffer[5] === 0xB1 &&
    buffer[6] === 0x1A &&
    buffer[7] === 0xE1
  ) return 'ole_doc';

  // DOCX/ZIP, случайно названный .doc.
  if (
    buffer[0] === 0x50 &&
    buffer[1] === 0x4B &&
    (
      (buffer[2] === 0x03 && buffer[3] === 0x04) ||
      (buffer[2] === 0x05 && buffer[3] === 0x06) ||
      (buffer[2] === 0x07 && buffer[3] === 0x08)
    )
  ) return 'zip_like';

  const start = buffer.subarray(0, Math.min(buffer.length, 64)).toString('latin1');
  if (/^\{\\rtf/i.test(start)) return 'rtf_like';
  if (/^\s*<(?:!doctype\s+html|html|\?xml)/i.test(start)) return 'html_or_xml_like';

  return 'unknown';
}

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const source = item.json || {};
  const sourceBinary = item.binary?.data || {};

  try {
    // Получаем реальные байты из binary storage n8n, а не копируем ссылку/ID,
    // которую некоторые community-ноды могут прочитать некорректно после распаковки.
    const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');

    const fileName = String(
      sourceBinary.fileName ||
      sourceBinary.filename ||
      source.documentFileName ||
      `extracted_document_${i + 1}.doc`
    );

    const mimeType = String(
      sourceBinary.mimeType ||
      source.mimeType ||
      'application/msword'
    );

    const rebuilt = await this.helpers.prepareBinaryData(
      buffer,
      fileName,
      mimeType
    );

    const magic = detectMagic(buffer);
    const warning = magic === 'ole_doc'
      ? 'Извлечённый DOC пересобран из реального binary buffer перед Universal File Extractor.'
      : `Файл имеет расширение .doc, но сигнатура определена как ${magic}. Binary пересобран перед Universal File Extractor.`;

    output.push({
      json: {
        ...source,
        docBinaryRebuilt: true,
        docBinaryMagic: magic,
        docBinarySize: buffer.length,
        parserWarning: [source.parserWarning, warning]
          .filter(Boolean)
          .join(' ')
      },
      binary: {
        data: rebuilt
      },
      pairedItem: { item: i }
    });
  } catch (error) {
    output.push({
      json: {
        ...source,
        cv_text: '',
        parsedText: '',
        parserStatus: 'doc_binary_rebuild_error',
        parserError: String(error?.message || error || ''),
        parserWarning: [
          source.parserWarning,
          'Не удалось получить и пересобрать реальные байты извлечённого DOC.'
        ].filter(Boolean).join(' '),
        docBinaryRebuilt: false,
        skipDocumentCollect: false
      },
      pairedItem: { item: i }
    });
  }
}

return output;
